"""Apply the Peng operator-release fix (requires the source-response fix). Python 3.9+, standard library only.

Run from the project root: python apply_peng_release_fix.py
Checks both file versions before writing; saves original files in a backup.
Use --check for a read-only compatibility check, --root PATH to select a repo.
"""
import argparse, base64, datetime, hashlib, json, os, tempfile, uuid, zlib
from pathlib import Path

PAYLOAD = ""

def normalized(raw):
    return raw.decode('utf-8-sig').replace('\r\n','\n')

def digest(text):
    return hashlib.sha256(text.encode('utf-8')).hexdigest()

def atomic_write(path, raw):
    temporary = None
    try:
        with tempfile.NamedTemporaryFile(dir=str(path.parent), prefix='.peng-memory-', delete=False) as f:
            temporary=Path(f.name); f.write(raw)
        os.replace(str(temporary), str(path))
    finally:
        if temporary is not None and temporary.exists():
            temporary.unlink()

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--root',type=Path,default=Path.cwd())
    parser.add_argument('--check',action='store_true')
    args=parser.parse_args(); root=args.root.resolve()
    payload=json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))
    pending={}
    for relative, item in payload.items():
        path=root/relative
        if not path.is_file():
            raise SystemExit('Project file missing: '+str(path)+'; run from the project root.')
        raw=path.read_bytes(); current=digest(normalized(raw))
        if digest(item['text']) != item['after']:
            raise SystemExit('Patch payload integrity check failed.')
        if current==item['after']:
            print('Already patched:',relative)
        elif current==item['before']:
            pending[relative]=(raw,item['text']); print('Compatible:',relative)
        else:
            raise SystemExit('Version mismatch: '+relative+'. No files were modified. Do not force overwrite; compare peng_release_fix.patch with your source.')
    if args.check or not pending:
        print('Check complete.' if args.check else 'Operator-release fix is already installed.')
        return
    backup=root/('peng_release_backup_'+datetime.datetime.now().strftime('%Y%m%d_%H%M%S')+'_'+uuid.uuid4().hex[:8])
    backup.mkdir()
    for relative,(raw,_) in pending.items():
        saved=backup/relative; saved.parent.mkdir(parents=True,exist_ok=True); saved.write_bytes(raw)
    changed=[]
    try:
        for relative,(raw,text) in pending.items():
            newline='\r\n' if b'\r\n' in raw else '\n'
            atomic_write(root/relative,text.replace('\n',newline).encode('utf-8'))
            changed.append(relative)
    except Exception:
        for relative in changed:
            atomic_write(root/relative,pending[relative][0])
        raise
    print('Installed. Original files:',backup)
    print('Normal incidence, x polarization, complex128 and factorization are unchanged.')

if __name__=='__main__':
    main()
